<?php require __DIR__.'/../includes/app.php'; need('System Administrator');$roles=q('SELECT role_id,role_name FROM roles')->fetchAll(PDO::FETCH_KEY_PAIR);
if($_SERVER['REQUEST_METHOD']==='POST'){chk();$p=$_POST;
 if($p['act']==='create'){if(strlen($p['password'])<8)flash('Password needs 8+ characters.','danger');elseif(q('SELECT 1 FROM users WHERE email=?',[$p['email']])->fetch())flash('Email already exists.','danger');else{
  q('INSERT INTO users(role_id,first_name,last_name,email,phone,password_hash,must_change_password) VALUES(?,?,?,?,?,?,1)',[$p['role_id'],$p['first_name'],$p['last_name'],$p['email'],$p['phone'],password_hash($p['password'],PASSWORD_DEFAULT)]);$uid=db()->lastInsertId();
  if($roles[$p['role_id']]==='Customer')q('INSERT INTO customers(user_id,customer_code,first_name,last_name,phone,email) VALUES(?,?,?,?,?,?)',[$uid,code('CUS'),$p['first_name'],$p['last_name'],$p['phone'],$p['email']]);audit('create_user','user',$uid);flash('User created.');}}
 elseif($p['act']==='status'&&$p['id']!=user()['id']){q('UPDATE users SET account_status=? WHERE user_id=?',[$p['status'],$p['id']]);audit('user_status','user',$p['id'],$p['status']);flash('Status updated.');}
 elseif($p['act']==='reset'&&strlen($p['password'])>=8){q('UPDATE users SET password_hash=?,must_change_password=1 WHERE user_id=?',[password_hash($p['password'],PASSWORD_DEFAULT),$p['id']]);audit('reset_password','user',$p['id']);flash('Password reset.');}else flash('No change made.','warning');
 header('Location: users.php');exit;}
head('User management');?>
<div class="card mb-4"><div class="card-header">Add a user</div><div class="card-body"><form method="post" class="row g-3"><?=csrf_f()?><input type="hidden" name="act" value="create">
<?php fld('first_name','First name','','text',null,'col-md-3',1);fld('last_name','Last name','','text',null,'col-md-3',1);fld('email','Email','','email',null,'col-md-3',1);fld('phone','Phone','','text',null,'col-md-3');fld('role_id','Role','','text',$roles,'col-md-4');fld('password','Temporary password (8+)','','password',null,'col-md-4',1);?>
<div class="col-md-4 d-flex align-items-end"><button class="btn btn-primary">Create user</button></div></form></div></div>
<div class="card"><div class="card-header">All users</div><div class="card-body table-responsive p-0"><table class="table table-hover align-middle"><thead><tr><th>Name<th>Email<th>Role<th>Status<th>Last login<th>Actions</thead>
<?php foreach(q('SELECT u.*,r.role_name FROM users u JOIN roles r USING(role_id) ORDER BY u.user_id')->fetchAll() as $x):?><tr><td><?=e($x['first_name'].' '.$x['last_name'])?><td><?=e($x['email'])?><td><?=e($x['role_name'])?><td><?=badge($x['account_status'])?><td class="small"><?=e($x['last_login_at']?:'never')?>
<td><?php if($x['user_id']!=user()['id']):?><form method="post" class="d-inline-flex gap-1"><?=csrf_f()?><input type="hidden" name="act" value="status"><input type="hidden" name="id" value="<?=$x['user_id']?>"><select name="status" class="form-select form-select-sm w-auto"><?php foreach(['active','inactive','suspended','pending'] as $s)echo '<option'.($s===$x['account_status']?' selected':'').'>'.$s.'</option>';?></select><button class="btn btn-sm btn-outline-primary">Set</button></form>
<form method="post" class="d-inline-flex gap-1 ms-2"><?=csrf_f()?><input type="hidden" name="act" value="reset"><input type="hidden" name="id" value="<?=$x['user_id']?>"><input type="password" name="password" placeholder="New password" class="form-control form-control-sm w-auto" minlength="8"><button class="btn btn-sm btn-outline-secondary">Reset</button></form><?php else:?><span class="text-muted small">You</span><?php endif;?></tr><?php endforeach;?></table></div></div><?php foot();
